const std::string message { "Test" };
const std::string getString() { return message; }

auto s1 { getString() };             // s1 推导为 std::string
const auto& s2 { getString() };      // 显式声明为 const 引用
decltype(getString()) s3 { getString() }; // 保留 getString() 的类型特征
decltype(auto) s4 { getString() };   // 按 decltype 规则推导
